"use client";
import React,{useEffect,useState} from "react";import Link from "next/link";import {useRouter} from "next/navigation";import api from "@/lib/api";
import {useResource,Notice,field,button,message} from "@/components/BillingUI";
interface Plan{id:number;name:string;availability:string}
export default function Page(){const router=useRouter();const {data,error}=useResource<Plan>("/api/packages");const [plan,setPlan]=useState("");const [count,setCount]=useState("1");const [prefix,setPrefix]=useState("");const [length,setLength]=useState("8");const [format,setFormat]=useState("ALPHANUMERIC");const [batch,setBatch]=useState("");const [giveaway,setGiveaway]=useState(false);const [saving,setSaving]=useState(false);const [note,setNote]=useState("");
 useEffect(()=>{api.get<{voucherPrefix:string|null;voucherCodeLength:number;voucherCodeFormat:string}>("/api/settings").then(r=>{if(r.data.voucherPrefix)setPrefix(r.data.voucherPrefix);if(r.data.voucherCodeLength)setLength(String(r.data.voucherCodeLength));if(r.data.voucherCodeFormat)setFormat(r.data.voucherCodeFormat);}).catch(()=>undefined);},[]);
 const save=async(e:React.FormEvent)=>{e.preventDefault();setSaving(true);try{await api.post("/api/vouchers",{packageId:Number(plan),count:Number(count),prefix,codeLength:Number(length),codeFormat:format,batchReference:batch,giveaway});router.push("/dashboard/vouchers");}catch(e){setNote(message(e));}finally{setSaving(false);}};
 return <div className="mx-auto max-w-5xl space-y-6"><Link href="/dashboard/vouchers" className="text-xs text-slate-500">Vouchers / Create</Link><h1 className="text-2xl font-semibold text-slate-900">Generate vouchers</h1><Notice text={error||note}/><form onSubmit={save} className="space-y-6 rounded-xl border border-slate-200 bg-white p-6"><div className="grid gap-6 sm:grid-cols-2"><label className="text-xs text-slate-700">Package *<select required value={plan} onChange={e=>setPlan(e.target.value)} className={field}><option value="">Select a package</option>{data.map(p=><option key={p.id} value={p.id}>{p.name} ({p.availability.toLowerCase()})</option>)}</select></label><label className="text-xs text-slate-700">Number of vouchers *<input required type="number" min="1" max="500" value={count} onChange={e=>setCount(e.target.value)} className={field}/></label><label className="text-xs text-slate-700">Voucher prefix<input maxLength={1} pattern="[A-Za-z]?" value={prefix} onChange={e=>setPrefix(e.target.value.toUpperCase())} className={field}/><small className="mt-2 block text-slate-500">Optional: one letter</small></label><label className="text-xs text-slate-700">Voucher code length *<select value={length} onChange={e=>setLength(e.target.value)} className={field}>{[5,6,7,8,9,10,11,12].map(n=><option key={n} value={n}>{n} characters</option>)}</select><small className="mt-2 block text-slate-500">Includes the prefix</small></label><label className="text-xs text-slate-700">Code format *<select value={format} onChange={e=>setFormat(e.target.value)} className={field}><option value="ALPHANUMERIC">Letters and numbers</option><option value="NUMERIC">Numbers</option><option value="LETTERS">Letters</option></select></label><label className="text-xs text-slate-700">Batch reference<input maxLength={80} value={batch} onChange={e=>setBatch(e.target.value)} placeholder="Auto-generated if empty" className={field}/></label></div><label className="flex gap-3 text-sm text-slate-700"><input type="checkbox" checked={giveaway} onChange={e=>setGiveaway(e.target.checked)}/>Giveaway — no revenue is recorded</label><p className="text-xs leading-6 text-slate-500">Voucher validity starts at first login, not when you generate it. Delivery is manual for now. Generating inventory does not record a sale.</p><div className="flex gap-4"><button disabled={saving} className={button}>{saving?"Generating…":"Create vouchers"}</button><Link href="/dashboard/vouchers" className="py-2 text-xs text-slate-500">Cancel</Link></div></form></div>;
}
